//! Hybrid forward pass (Stage-1, f32, prefill, single sequence). Per layer dispatches to a
//! linear-attention (Gated DeltaNet) or full-attention mixer, then SwiGLU FFN. Matches
//! llama.cpp src/models/qwen35.cpp node-for-node.

// lane/clippy-zero-restore-20260901: index loops here mirror the llama.cpp reference
// node-for-node (header above); iterator reshapes are not bit-neutral by inspection.
#![allow(clippy::needless_range_loop)]

use crate::Engine;
use crate::cache::Cache;
use cudarc::driver::CudaSlice;
use memra_gguf::config::{ModelConfig, SwigluClamp};

/// Resident trunk transients for the eager prime (piecewise-graph foundation; see
/// HybridModel::prime_slabs). Every live buffer prefix is fully overwritten before use per prime;
/// capacity beyond the current token count must never cross a shape-sensitive boundary.
pub struct PrimeSlabs {
    pub t_cap: usize,
    pub h: CudaSlice<f32>,
    pub x1: CudaSlice<f32>,
    pub z: CudaSlice<f32>,
    pub act: CudaSlice<f32>,
    pub xa: CudaSlice<f32>,
    pub xb: CudaSlice<f32>,
    pub h16: CudaSlice<u8>,
    pub z16: CudaSlice<u8>,
    /// piecewise boundary slabs (increment 2): GEMM outputs land here so the
    /// downstream captured segments see fixed addresses.
    pub gate: CudaSlice<f32>, // t * n_ff_max
    pub up: CudaSlice<f32>,      // t * n_ff_max
    pub ffn_out: CudaSlice<f32>, // t * n_embd
    /// piecewise increment 3: per-layer S-glue segment graphs (down-add + next
    /// attn-norm, ALL-slab IO, zero in-graph allocations -> keeperless capture is
    /// clean). Baked at this t_cap; replay only when t == t_cap. seg_glue[il] fires
    /// between layer il and il+1 (ping-pong parity is deterministic per il).
    pub seg_glue: Vec<Option<cudarc::driver::CudaGraph>>,
    /// increment 5 (core-split edition): the mixer out-GEMM writes _into_ `mixed`
    /// directly (no staging copy — the increment-4 copy route was refuted), making
    /// S-mid [add + post-norm] all-slab and capturable.
    pub mixed: CudaSlice<f32>,
    pub seg_mid: Vec<Option<cudarc::driver::CudaGraph>>,
    pub seg_t: usize,
}

// Split prime ranges cannot enter the full-range segment-graph arm, and every slab access
// is serialized by its device mutex after binding that device's CUDA context on the thread.
unsafe impl Send for PrimeSlabs {}

/// Shared-expert gate+up at t==1: NVFP4 fused2 (the ornith15/qwen35moe NVFP4 mints keep
/// gate/up_shexp uniformly NVFP4, so the Q8-only fused2 never fired there and the pair fell
/// to two mr2 singles + two re-quantizes of the same z — 2 of the 8 unfused launches/layer
/// the orndecode B=1 census ranked at 17.1%), else the Q8_0 fused2 (the Q8 35B mint), else
/// two singles. ONE helper for all three shexp dispatch sites — the MEMRA_GDN_MMA
/// three-read-sites defect is the precedent for not inlining this thrice. Fusion law
/// everywhere: per (tensor,row) the fused seg body is verbatim, so fused == singles
/// bit-identically, and the shared (zq, zd) is the same quantize each single recomputes.
fn shexp_gate_up_t1(
    e: &Engine,
    gate_shexp: &crate::model::GpuTensor,
    up_shexp: &crate::model::GpuTensor,
    z: &CudaSlice<f32>,
    zq8: Option<&(CudaSlice<i8>, CudaSlice<f32>)>,
) -> Result<(CudaSlice<f32>, CudaSlice<f32>), Box<dyn std::error::Error>> {
    let is_nvfp4 = |w: &crate::model::GpuTensor| matches!(w, crate::model::GpuTensor::Quant { qtype, .. } if *qtype == crate::QT_NVFP4);
    if is_nvfp4(gate_shexp) && is_nvfp4(up_shexp) {
        // Reuse the caller's t==1 z-quantize when one exists (the zq8 seam the dev arm
        // already consumes) — the helper's own quantize is the identical kernel on the
        // identical input, so this drops one launch per MoE layer without moving a byte.
        let pair = match zq8 {
            Some((zq, zd)) => e.matmul_nvfp4_fused2(gate_shexp, up_shexp, zq, zd, 1)?,
            None => {
                let (zq, zd) = e.quantize_q8_1(z, 1, gate_shexp.in_features())?;
                e.matmul_nvfp4_fused2(gate_shexp, up_shexp, &zq, &zd, 1)?
            }
        };
        if let Some(pair) = pair {
            return Ok(pair);
        }
    }
    match e.matmul_q8_fused2_x(gate_shexp, up_shexp, z)? {
        Some(pair) => Ok(pair),
        None => Ok((e.matmul(gate_shexp, z, 1)?, e.matmul(up_shexp, z, 1)?)),
    }
}

fn active_matrix_values(
    available: usize,
    rows: usize,
    columns: usize,
    label: &str,
) -> Result<usize, String> {
    let required = rows
        .checked_mul(columns)
        .ok_or_else(|| format!("{label} shape overflows: {rows}x{columns}"))?;
    if available < required {
        return Err(format!(
            "{label} has {available} values, fewer than the active {rows}x{columns} ({required})"
        ));
    }
    Ok(required)
}

fn step_grouped_decode_shape(prefill: bool, tokens: usize) -> bool {
    !prefill && tokens == 1
}

fn parse_step_ep_grouped_prefill(value: Option<&str>) -> Result<bool, String> {
    match value {
        None | Some("") | Some("0") => Ok(false),
        Some("1") => Ok(true),
        Some(value) => Err(format!(
            "MEMRA_STEP_EP_GROUPED_PREFILL={value:?} is invalid; expected 0 or 1"
        )),
    }
}

fn step_ep_grouped_prefill_enabled() -> Result<bool, String> {
    parse_step_ep_grouped_prefill(
        std::env::var("MEMRA_STEP_EP_GROUPED_PREFILL")
            .ok()
            .as_deref(),
    )
}

fn step_grouped_prefill_shape(enabled: bool, prefill: bool, tokens: usize) -> bool {
    enabled && prefill && (PRIME_MIN_T..=crate::cache::PRIME_CHUNK_MAX_TOKENS).contains(&tokens)
}

fn parse_step_tp_prefill(value: Option<&str>) -> Result<bool, String> {
    match value {
        None | Some("") | Some("0") => Ok(false),
        Some("1") => Ok(true),
        Some(value) => Err(format!(
            "MEMRA_STEP_TP_PREFILL={value:?} is invalid; expected 0 or 1"
        )),
    }
}

fn step_tp_prefill_enabled() -> Result<bool, String> {
    parse_step_tp_prefill(std::env::var("MEMRA_STEP_TP_PREFILL").ok().as_deref())
}

fn validate_step_prime_batch_modes(tp_prefill: bool, grouped_prefill: bool) -> Result<(), String> {
    if grouped_prefill && !tp_prefill {
        return Err("MEMRA_STEP_EP_GROUPED_PREFILL=1 requires MEMRA_STEP_TP_PREFILL=1".into());
    }
    if tp_prefill {
        return Err(
            "Step TP4 cross-request prime batching did not clear the live-server performance \
             gate; use per-session grouped prefill"
                .into(),
        );
    }
    Ok(())
}

fn step_tp_prefill_shape(
    enabled: bool,
    tokens: usize,
    ranks: usize,
    native_p2p: bool,
    has_rank_local_attention: bool,
) -> bool {
    // TP2 admitted 2026-08-25 behind the same off-by-default door. The prefill body is
    // rank-count-generic (every geometry check divides by `ranks`); only this shape ever
    // named 4. TP4's high-context NO-GO was a TRANSPORT verdict — token-row column
    // gathers plus remote O blocks issue ~61,440 peer copies per 4K attention layer on
    // that placement — which is not evidence about a 2-card native-P2P placement that
    // reduces O rank-locally. TP2 is UNQUALIFIED until its own prefill argmax + TTFT
    // receipts land; the door stays off by default.
    enabled
        && tokens >= PRIME_MIN_T
        && matches!(ranks, 2 | 4)
        && native_p2p
        && has_rank_local_attention
}

fn empty_cache_layers<T>(n: usize) -> Vec<Option<T>> {
    std::iter::repeat_with(|| None).take(n).collect()
}

fn prime_cache_stage_for_layer(fence: &[usize], layer: usize) -> usize {
    debug_assert!(fence.len() >= 3);
    match fence[1..fence.len() - 1].binary_search(&layer) {
        Ok(index) => index + 1,
        Err(index) => index,
    }
}

fn move_prime_cache_layers<T>(
    parent: &mut [Option<T>],
    stages: &mut [Vec<Option<T>>],
    fence: &[usize],
) {
    assert_eq!(stages.len() + 1, fence.len());
    assert!(stages.iter().all(|stage| stage.len() == parent.len()));
    for (layer, value) in parent.iter_mut().enumerate() {
        let stage = prime_cache_stage_for_layer(fence, layer);
        debug_assert!(stages[stage][layer].is_none());
        stages[stage][layer] = value.take();
    }
}

#[cfg(test)]
fn restore_prime_cache_layers<T>(
    parent: &mut [Option<T>],
    stages: &mut [Vec<Option<T>>],
    fence: &[usize],
) {
    assert_eq!(stages.len() + 1, fence.len());
    assert!(stages.iter().all(|stage| stage.len() == parent.len()));
    for (layer, value) in parent.iter_mut().enumerate() {
        let stage = prime_cache_stage_for_layer(fence, layer);
        debug_assert!(value.is_none());
        *value = stages[stage][layer].take();
    }
}

/// Temporarily move a PP cache's layer state into independently-owned stage shells. The stage
/// walkers then receive disjoint `&mut Cache` values and can run on separate host threads without
/// aliasing. GPU buffers are moved, not copied; Drop restores every layer and publishes the last
/// position completed by every stage.
struct PrimeCacheStages<'a> {
    parent: &'a mut Cache,
    fence: Vec<usize>,
    stages: Vec<std::sync::Mutex<Cache>>,
    committed: bool,
}

impl<'a> PrimeCacheStages<'a> {
    fn new(parent: &'a mut Cache, fence: &[usize]) -> Self {
        let n = parent.kv.len();
        assert_eq!(parent.recur.len(), n, "cache layer vectors disagree");
        assert_eq!(parent.tp_kv.len(), n, "cache layer vectors disagree");
        assert_eq!(parent.latent.len(), n, "cache layer vectors disagree");
        let n_stages = fence.len().checked_sub(1).expect("PP cache fence is empty");
        assert!((2..=4).contains(&n_stages), "PP cache needs 2..=4 stages");
        assert_eq!(fence[0], 0, "PP cache fence must start at layer zero");
        assert!(
            fence.windows(2).all(|pair| pair[0] < pair[1]),
            "PP cache fence must be strictly increasing"
        );
        assert!(fence[n_stages] <= n, "PP cache fence exceeds {n} layers");

        let mut latent: Vec<_> = (0..n_stages).map(|_| empty_cache_layers(n)).collect();
        let mut g5_recur: Vec<_> = (0..n_stages).map(|_| empty_cache_layers(n)).collect();
        let mut g5_latent: Vec<_> = (0..n_stages).map(|_| empty_cache_layers(n)).collect();
        let mut kv: Vec<_> = (0..n_stages).map(|_| empty_cache_layers(n)).collect();
        let mut tp_kv: Vec<_> = (0..n_stages).map(|_| empty_cache_layers(n)).collect();
        let mut recur: Vec<_> = (0..n_stages).map(|_| empty_cache_layers(n)).collect();
        move_prime_cache_layers(&mut parent.kv, &mut kv, fence);
        move_prime_cache_layers(&mut parent.tp_kv, &mut tp_kv, fence);
        move_prime_cache_layers(&mut parent.recur, &mut recur, fence);

        move_prime_cache_layers(&mut parent.latent, &mut latent, fence);
        move_prime_cache_layers(&mut parent.glm5_tp_recur, &mut g5_recur, fence);
        move_prime_cache_layers(&mut parent.glm5_tp_latent_peer, &mut g5_latent, fence);
        let pos = parent.pos;
        let max_ctx = parent.max_ctx;
        // Indexed rather than zipped: six per-stage layer vectors (main's kv/tp_kv/recur plus
        // this lane's latent/glm5_tp_recur/glm5_tp_latent_peer) do not read as a zip chain, and
        // a nested-tuple pattern is exactly where a field silently lands on the wrong stage.
        let stages = (0..n_stages)
            .map(|stage| {
                std::sync::Mutex::new(Cache {
                    kv: std::mem::take(&mut kv[stage]),
                    tp_kv: std::mem::take(&mut tp_kv[stage]),
                    recur: std::mem::take(&mut recur[stage]),
                    latent: std::mem::take(&mut latent[stage]),
                    glm5_tp_recur: std::mem::take(&mut g5_recur[stage]),
                    glm5_tp_latent_peer: std::mem::take(&mut g5_latent[stage]),
                    pos,
                    max_ctx,
                    tainted: false,
                    last_logits_dev: None,
                    dflash_taps: None,
                    hc_taps: None,
                    // Per-stage split caches start with no captured graphs: a run graph bakes the
                    // state pointers of the cache it was captured against, and this one is new.
                    glm5_decode_graph: None,
                })
            })
            .collect();
        Self {
            parent,
            fence: fence.to_vec(),
            stages,
            committed: false,
        }
    }

    fn pp2_parts(&mut self) -> (&mut Cache, &mut Cache) {
        assert_eq!(self.stages.len(), 2);
        let (stage0, stage1) = self.stages.split_at_mut(1);
        (
            stage0[0]
                .get_mut()
                .unwrap_or_else(|poisoned| poisoned.into_inner()),
            stage1[0]
                .get_mut()
                .unwrap_or_else(|poisoned| poisoned.into_inner()),
        )
    }

    fn stages(&self) -> &[std::sync::Mutex<Cache>] {
        &self.stages
    }

    fn commit(&mut self) {
        self.committed = true;
    }
}

impl Drop for PrimeCacheStages<'_> {
    fn drop(&mut self) {
        let n = self.parent.kv.len();
        for i in 0..n {
            let stage = prime_cache_stage_for_layer(&self.fence, i);
            let source = self.stages[stage]
                .get_mut()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            debug_assert!(self.parent.kv[i].is_none());
            debug_assert!(self.parent.tp_kv[i].is_none());
            debug_assert!(self.parent.recur[i].is_none());
            debug_assert!(self.parent.latent[i].is_none());
            self.parent.kv[i] = source.kv[i].take();
            self.parent.tp_kv[i] = source.tp_kv[i].take();
            self.parent.recur[i] = source.recur[i].take();
            self.parent.latent[i] = source.latent[i].take();
            self.parent.glm5_tp_recur[i] = source.glm5_tp_recur[i].take();
            self.parent.glm5_tp_latent_peer[i] = source.glm5_tp_latent_peer[i].take();
        }
        self.parent.pos = self
            .stages
            .iter_mut()
            .map(|stage| {
                stage
                    .get_mut()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .pos
            })
            .min()
            .unwrap_or(self.parent.pos);
        if !self.committed {
            self.parent.mark_tainted();
        }
    }
}

/// Fail-stop transaction marker for concat-prime paths. These paths mutate several independent
/// caches before their final epilogue can fail; an error must make every member permanently
/// ineligible for retry/reuse rather than replaying a queue over partially advanced state.
struct CacheTaintGuard {
    caches: Vec<*mut Cache>,
    committed: bool,
}

impl CacheTaintGuard {
    fn arm(caches: &mut [&mut Cache]) -> Self {
        Self {
            caches: caches
                .iter_mut()
                .map(|cache| *cache as *mut Cache)
                .collect(),
            committed: false,
        }
    }

    fn commit(&mut self) {
        self.committed = true;
    }
}

impl Drop for CacheTaintGuard {
    fn drop(&mut self) {
        if self.committed {
            return;
        }
        for cache in &self.caches {
            // SAFETY: `arm` receives the function's unique cache references. The guard never
            // escapes that call or dereferences them until unwind/return after active borrows end.
            unsafe { (&mut **cache).mark_tainted() };
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct PrimePpWaveSlot {
    wave: usize,
    slot: usize,
}

#[derive(Debug)]
enum PrimePpSignal {
    Slot(PrimePpWaveSlot),
    Error(String),
}

#[derive(Default)]
struct PrimePpWaveCredits {
    next_wave: usize,
    pending: std::collections::VecDeque<PrimePpWaveSlot>,
}

impl PrimePpWaveCredits {
    fn release_required(&self) -> Option<PrimePpWaveSlot> {
        (self.pending.len() == 2).then(|| self.pending[0])
    }

    fn record_release(&mut self, released: PrimePpWaveSlot) -> Result<(), String> {
        let expected =
            self.pending.front().copied().ok_or_else(|| {
                "prime PP received a slot release with no pending wave".to_string()
            })?;
        if released != expected {
            return Err(format!(
                "prime PP slot release {:?} does not match oldest pending {:?}",
                released, expected
            ));
        }
        self.pending.pop_front();
        Ok(())
    }

    fn record_send(&mut self, sent: PrimePpWaveSlot) -> Result<(), String> {
        if sent.wave != self.next_wave {
            return Err(format!(
                "prime PP sent wave {} while wave {} was next",
                sent.wave, self.next_wave
            ));
        }
        if sent.slot >= 2 {
            return Err(format!(
                "prime PP boundary returned invalid slot {}",
                sent.slot
            ));
        }
        if self.pending.iter().any(|pending| pending.slot == sent.slot) {
            return Err(format!(
                "prime PP reused slot {} before its exact-wave release",
                sent.slot
            ));
        }
        self.pending.push_back(sent);
        self.next_wave += 1;
        Ok(())
    }
}

fn recv_prime_pp_signal(
    receiver: &std::sync::mpsc::Receiver<PrimePpSignal>,
    expected: PrimePpWaveSlot,
    exact_slot: bool,
    label: &str,
) -> Result<PrimePpWaveSlot, String> {
    match receiver.recv() {
        Ok(PrimePpSignal::Error(error)) => Err(error),
        Ok(PrimePpSignal::Slot(received))
            if received.wave == expected.wave
                && (!exact_slot || received.slot == expected.slot) =>
        {
            if received.slot >= 2 {
                Err(format!(
                    "{label}: wave {} carried invalid slot {}",
                    received.wave, received.slot
                ))
            } else {
                Ok(received)
            }
        }
        Ok(PrimePpSignal::Slot(received)) => Err(format!(
            "{label}: expected wave/slot {:?}, received {:?}",
            expected, received
        )),
        Err(_) => Err(format!(
            "{label}: channel closed while waiting for wave {}",
            expected.wave
        )),
    }
}

fn send_prime_pp_signal(
    sender: &std::sync::mpsc::Sender<PrimePpSignal>,
    signal: PrimePpSignal,
    label: &str,
) -> Result<(), String> {
    sender
        .send(signal)
        .map_err(|_| format!("{label}: channel closed"))
}

struct PrimePpWave<'a> {
    start: usize,
    end: usize,
    tokens: &'a [u32],
}

struct PrimePpStageChannels {
    incoming: Option<std::sync::mpsc::Receiver<PrimePpSignal>>,
    release_upstream: Option<std::sync::mpsc::Sender<PrimePpSignal>>,
    outgoing: std::sync::mpsc::Sender<PrimePpSignal>,
    released_downstream: std::sync::mpsc::Receiver<PrimePpSignal>,
}

impl PrimePpStageChannels {
    fn notify_failure(&self, error: &str) {
        if let Some(upstream) = &self.release_upstream {
            let _ = upstream.send(PrimePpSignal::Error(error.to_string()));
        }
        let _ = self.outgoing.send(PrimePpSignal::Error(error.to_string()));
    }
}

/// The DSA k-pool indexer's resident state, borrowed for one `mla_attn_core` call.
///
/// TWO PLANES, DIFFERENT LIFETIMES. `state` is the packed `[k_norm | gate]` row per cached token
/// (`LatentKvLayer::index_rows`); it is append-only and grows with the cache. `pool_keys` is the
/// collapsed key per COMPLETE pool of `pool` such rows, and it is the residency win: a pool's key
/// is final the moment its last row lands, so pools `[0, *ready)` are never recomputed and each
/// call builds only the pools its own tokens completed. `ready` is written back through the
/// borrow, so the caller must persist it alongside the buffers.
///
/// `pool_keys` is `Option` because its size needs the indexer's `pool`, which the state plan does
/// not carry — `mla_kpool_indices` allocates it on first use and leaves it resident thereafter.
/// A caller that hands over a fresh `None` every call (the stateless arm) gets the old
/// rebuild-everything behaviour, which is exactly right when the state itself is per-call.
/// The MLA core's PRE/POST handoff buffers, one set per session, reused by every MLA layer
/// (lane/glm5-mla-capture-20260904, door `MEMRA_MLA_SEG_WS`). WHY: a captured PRE graph and a
/// captured POST graph must hand each other buffers at STABLE addresses; allocations inside ONE
/// capture are fine (they become graph alloc nodes, which is how the KDA runs already capture),
/// but two graphs cannot hand each other a fresh allocation. Every MLA layer of a glm5 model
/// shares one `MlaGeom`, so one set serves all eleven, sequentially, exactly as the eager walk's
/// fresh buffers do. BYTE-IDENTICAL by construction: the same kernels write the same values in
/// the same order to a different address, and every consumer reads the value, never the address
/// (door W's contract, `MEMRA_VERIFY_WS`).
/// Engagement counter for `MEMRA_MLA_SEG_WS`; gates take a delta.
pub static MLA_SEG_WS_DISPATCHES: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);
static MLA_MID_LIVE_DISPATCHES: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
/// Decode sites served by the BF16 absorb planes (`MEMRA_MLA_ABSORB_BF16=1`).
pub static MLA_ABSORB_BF16_DISPATCHES: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);

/// Snapshot of [`MLA_SEG_WS_DISPATCHES`].
pub fn mla_seg_ws_dispatches() -> u64 {
    MLA_SEG_WS_DISPATCHES.load(std::sync::atomic::Ordering::Relaxed)
}

/// A q8_1 activation pair (quants, per-32 scales).
pub(crate) type Q8Pair = (CudaSlice<i8>, CudaSlice<f32>);

/// One hc layer and its hyper-connection weights, as the segment walk borrows them.
pub(crate) type WsLayerRef<'a> = (&'a crate::hybrid::HybridLayer, &'a crate::hyper::HyperLayer);

/// A segment of the t=1 workspace walk (see `hyper_range_decode_ws_segments`).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub(crate) enum WsSeg {
    Layer(usize),
    MlaPre(usize),
    /// The MLA middle (append, k-pool selection, attention, decompress, `wo`) as fixed-geometry
    /// live twins reading the stage's `pos_d` (`MEMRA_GLM5_GRAPH_MLA_MID`); writes `mla_mixed`.
    MlaMid(usize),
    MlaFfn(usize),
}

pub(crate) struct MlaSegWs {
    pub q_nope: CudaSlice<f32>,
    pub q_pe: CudaSlice<f32>,
    pub q_an: CudaSlice<f32>,
    pub c_kv_n: CudaSlice<f32>,
    pub k_pe: CudaSlice<f32>,
    /// `(nh, dn, dr, r, q_lora)` this set was sized for; another geometry refuses by name.
    /// q8_1 pairs of `h` and `q_an` from the last PRE (quantize-once-share); the MID's indexer
    /// reads them, the next PRE overwrites them.
    pub h_q8: Option<Q8Pair>,
    pub q_q8: Option<Q8Pair>,
    pub sig: (usize, usize, usize, usize, usize),
}

impl MlaSegWs {
    /// Size one set for `t = 1` decode at this layer's geometry.
    pub(crate) fn new(
        e: &Engine,
        nh: usize,
        dn: usize,
        dr: usize,
        r: usize,
        q_lora: usize,
    ) -> Result<Self, Box<dyn std::error::Error>> {
        Ok(Self {
            q_nope: e.uninit(nh * dn)?,
            q_pe: e.uninit((nh * dr).max(1))?,
            q_an: e.uninit(q_lora)?,
            c_kv_n: e.uninit(r)?,
            k_pe: e.uninit(dr.max(1))?,
            h_q8: None,
            q_q8: None,
            sig: (nh, dn, dr, r, q_lora),
        })
    }
}

/// The three planes segment MID reads, from either the owned `MlaPreOut` or the pooled
/// [`MlaSegWs`].
pub(crate) struct MlaMidIn<'a> {
    pub q_an: &'a CudaSlice<f32>,
    pub c_kv_n: &'a CudaSlice<f32>,
    pub k_pe: &'a CudaSlice<f32>,
    /// q8_1 pairs of `h` and `q_an` the PRE segment already quantized for its own projections
    /// (quantize-once-share, 2026-09-05): the indexer's three projections on `h` and one on
    /// `q_an` reuse them instead of re-quantizing the same rows.
    pub h_q8: Option<&'a Q8Pair>,
    pub q_q8: Option<&'a Q8Pair>,
}

/// `Engine::matmul` for a row several t=1 projections share: quantize it to q8_1 ONCE (lazily,
/// and only when the weight is on the mmvq fast path), then run the fast path on the pair.
/// The same quantize kernel over the same row and the same matvec kernel: the same bytes as
/// `matmul` per call, one launch fewer per additional sharer. `rows_exact` keeps the exactness
/// harness path untouched.
fn mm_shared(
    e: &Engine,
    w: &crate::model::GpuTensor,
    x: &CudaSlice<f32>,
    m: usize,
    pair: &mut Option<Q8Pair>,
    rows_exact: bool,
) -> Result<CudaSlice<f32>, Box<dyn std::error::Error>> {
    if rows_exact {
        return e.matmul_rows_exact(w, x, m);
    }
    if e.mmvq_fast_eligible(w, m) {
        if pair.is_none() {
            *pair = Some(e.quantize_q8_1(x, m, w.in_features())?);
        }
        let (aq, ad) = pair.as_ref().expect("filled above");
        if let Some(y) = e.matmul_q8_fast(w, aq, ad, m)? {
            return Ok(y);
        }
    }
    e.matmul(w, x, m)
}

/// Read-only twin of [`mm_shared`]: use a pair a producer left, never quantize.
fn mm_with_pair(
    e: &Engine,
    w: &crate::model::GpuTensor,
    x: &CudaSlice<f32>,
    m: usize,
    pair: Option<&Q8Pair>,
    rows_exact: bool,
) -> Result<CudaSlice<f32>, Box<dyn std::error::Error>> {
    if rows_exact {
        return e.matmul_rows_exact(w, x, m);
    }
    if let Some((aq, ad)) = pair
        && let Some(y) = e.matmul_q8_fast(w, aq, ad, m)?
    {
        return Ok(y);
    }
    e.matmul(w, x, m)
}

